class Solution {
  public int lastRemaining(int n) {
    int head = 1, step = 1;
    boolean left = true;
    while (n > 1) {
      // the head moves when eliminating from the left, or from the right with an odd count
      if (left || n % 2 == 1) head += step;
      step *= 2;
      n /= 2;
      left = !left;
    }
    return head;
  }
}
